import{_ as i,a0 as l,w as o,s as r,ao as d,I as p,x as n,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"在 Xfce 會話中保存窗口的位置 | LCTT x X-CMD","titleTemplate":false,"description":"在 Xfce 會話中保存窗口的位置 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Xfce 會話中保存窗口的位置 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Xfce 會話中保存窗口的位置 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171216 Saving window position in Xfce session","title":"在 Xfce 會話中保存窗口的位置","tag":"201801","desc":""},"relativePath":"201801/20171216 Saving window position in Xfce session.md","filePath":"[post].md"}'),f={name:"201801/20171216 Saving window position in Xfce session.md"};function c(m,s,u,g,C,b){const e=l("Link");return o(),r("div",null,[s[13]||(s[13]=d(`<h1 id="在-xfce-會話中保存窗口的位置" tabindex="-1">在 Xfce 會話中保存窗口的位置 <a class="header-anchor" href="#在-xfce-會話中保存窗口的位置" aria-label="Permalink to “在 Xfce 會話中保存窗口的位置”">​</a></h1><p>摘要：如果你發現 Xfce 會話不能保存窗口的位置，那麼啓用“登出時保存”，然後登出再重新登錄一次，可能就能永久修復這個問題了（如果你想要保持相同的會話，再次登錄時恢復的話）。 下面是詳細內容。</p><p>我用 Xfce 作桌面有些年頭了，但是每次重啓後進入之前保存的會話時總會有問題出現。 登錄後， 之前會話中保存的應用都會啓動， 但是所有的工作區和窗口位置數據都會丟失， 導致所有應用都堆在默認工作區中，亂糟糟的。</p><p>多年來，很多人都報告過這個問題（Ubuntu、Xfce 以及 Red Hat 的 bug 追蹤系統中都有登記）。 雖然 Xfce4.10 中已經修復過了一個相關 bug， 但是我用的 Xfce4.12 依然有這個問題。 如果不是我的其中一個系統能夠正常的恢復各個窗口的位置，我幾乎都要放棄找出問題的原因了（事實上我之前已經放棄過很多次了）。</p><p>今天，我深入對比了兩個系統的不同點，最終解決了這個問題。 我現在就把結果寫出來， 以防有人也遇到相同的問題。</p><p>提前的一些説明：</p><ol><li>由於這個筆記本只有我在用，因此我幾乎不登出我的 Xfce 會話。 我一般只是休眠然後喚醒，除非由於要對內核打補丁才進行重啓， 或者由於某些改動損毀了休眠鏡像導致系統從休眠中喚醒時卡住了而不得不重啓。 另外，我也很少使用 Xfce 工具欄上的重啓按鈕重啓；一般我只是運行一下 <code>reboot</code>。</li><li>我會使用 xterm 和 Emacs， 這些不太複雜的 X 應用無法記住他們自己的窗口位置。</li></ol><p>Xfce 將會話信息保存到主用户目錄中的 <code>.cache/sessions</code> 目錄中。在經過仔細檢查後發現，在正常的系統中有兩類文件存儲在該目錄中，而在非正常的系統中，只有一類文件存在該目錄下。</p><p>其中一類文件的名字類似 <code>xfce4-session-hostname:0</code> 這樣的，其中包含的內容類似下面這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Client9_ClientId=2a654109b-e4d0-40e4-a910-e58717faa80b</span></span>
<span class="line"><span>Client9_Hostname=local/hostname</span></span>
<span class="line"><span>Client9_CloneCommand=xterm</span></span>
<span class="line"><span>Client9_RestartCommand=xterm，-xtsessionID，2a654109b-e4d0-40e4-a910-e58717faa80b</span></span>
<span class="line"><span>Client9_Program=xterm</span></span>
<span class="line"><span>Client9_UserId=user</span></span></code></pre></div><p>這個文件記錄了所有正在運行的程序。如果你進入“設置 -&gt; 會話和啓動”並清除會話緩存， 就會刪掉這種文件。 當你保存當前會話時， 又會創建這種文件。 這就是 Xfce 知道要啓動哪些應用的原因。 但是請注意，上面並沒有包含任何窗口位置的信息。 （我還曾經以為可以根據會話 ID 來找到其他地方的一些相關信息，但是並沒有）。</p><p>正常工作的系統在目錄中還有另一類文件，名字類似 <code>xfwm4-2d4c9d4cb-5f6b-41b4-b9d7-5cf7ac3d7e49.state</code> 這樣的。 其中文件內容類似下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[CLIENT] 0x200000f</span></span>
<span class="line"><span>[CLIENT_ID] 2a9e5b8ed-1851-4c11-82cf-e51710dcf733</span></span>
<span class="line"><span>[CLIENT_LEADER] 0x200000f</span></span>
<span class="line"><span>[RES_NAME] xterm</span></span>
<span class="line"><span>[RES_CLASS] XTerm</span></span>
<span class="line"><span>[WM_NAME] xterm</span></span>
<span class="line"><span>[WM_COMMAND] (1) &quot;xterm&quot;</span></span>
<span class="line"><span>[GEOMETRY] (860，35，817，1042)</span></span>
<span class="line"><span>[GEOMETRY-MAXIMIZED] (860，35，817，1042)</span></span>
<span class="line"><span>[SCREEN] 0</span></span>
<span class="line"><span>[DESK] 2</span></span>
<span class="line"><span>[FLAGS] 0x0</span></span></code></pre></div><p>注意這裏的 <code>GEOMETRY</code> 和 <code>DESK</code> 記錄的正是我們想要的窗口位置以及工作區號。因此不能保存窗口位置的原因就是因為缺少這個文件。</p><p>繼續深入下去，我發現當你明確地手工保存會話時，之後保存第一個文件而不會保存第二個文件。 但是當登出保存會話時則會保存第二個文件。 因此， 我進入“設置 -&gt; 會話和啓動”中，在“通用”標籤頁中啓用登出時自動保存會話， 然後登出後再進來， 然後， 第二個文件就出現了。 再然後我又關閉了登出時自動保存會話。（因為我一般在排好屏幕後就保存一個會話， 但是我不希望做出的改變也會影響到這個保存的會話， 如有必要我會明確地手工進行保存），現在我的窗口位置能夠正常的恢復了。</p><p>這也解釋了為什麼有的人會有問題而有的人沒有問題： 有的人可能一直都是用登出按鈕重啓，而有些人則是手工重啓（或者僅僅是由於系統崩潰了才重啓）。</p><p>順帶一提，這類問題， 以及為解決問題而付出的努力，正是我贊同為軟件存儲的狀態文件編寫 man 頁或其他類似文檔的原因。 為用户編寫文檔，不僅能幫助別人深入挖掘產生奇怪問題的原因， 也能讓軟件作者注意到軟件中那些奇怪的東西， 比如將會話狀態存儲到兩個獨立的文件中去。</p><hr>`,18)),p("p",null,[s[1]||(s[1]=n("via: ",-1)),a(e,{href:"https://www.eyrie.org/~eagle/journal/2017-12/001.html"},{default:t(()=>[...s[0]||(s[0]=[n("https://www.eyrie.org/~eagle/journal/2017-12/001.html",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=n("作者：",-1)),a(e,{href:"https://www.eyrie.org"},{default:t(()=>[...s[2]||(s[2]=[n("J. R. R. Tolkien",-1)])]),_:1}),s[6]||(s[6]=n(" 譯者：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[7]||(s[7]=n(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[10]||(s[10]=n("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[n("LCTT",-1)])]),_:1}),s[11]||(s[11]=n(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[n("Linux中國",-1)])]),_:1}),s[12]||(s[12]=n(" 榮譽推出",-1))])])}const X=i(f,[["render",c]]);export{h as __pageData,X as default};
